using UnityEngine;
namespace NoiteSemFim {
[Serializable] public class FavoriteBuild {public string name;public int startingWeapon=-1;public int hero,armor=-1,talisman=-1,dragon=-1,curse=-1,level=1,target;public bool manual;public int[] weapons=new int[6],passives=new int[6];public bool[] evolved=new bool[6];public float dps,damage,seconds;public int hits;}
public sealed partial class SurvivorGame {
 string labMeasurementKey="";
 string LabFingerprint()=>heroIndex+"/"+SelectedWeaponChoice+"/"+labLevel+"/"+labTarget+"/"+labArmor+"/"+labTalisman+"/"+labDragon+"/"+labCurse+"/"+manualAim+"/"+string.Join(",",labWeapons)+"/"+string.Join(",",labPassives)+"/"+string.Join(",",labEvolved);
 string favoriteName="Minha build";int favoriteSlot;ScreenState favoritesReturn;
 SaveData FavoritesAccount=>buildLabActive?labOriginalSave:save;
 List<FavoriteBuild> Favorites {get{var a=FavoritesAccount;if(a.favorites==null)a.favorites=new List<FavoriteBuild>();return a.favorites;}}
 void OpenFavorites(){favoritesReturn=buildLabActive?ScreenState.BuildLab:ScreenState.Menu;state=ScreenState.Favorites;}
 void CloseFavorites(){state=favoritesReturn;}
 bool SaveFavorite(int slot){if(!buildLabActive||slot<0||slot>=5)return false;var b=new FavoriteBuild{name=(favoriteName??"").Trim(),hero=heroIndex,startingWeapon=SelectedWeaponChoice,armor=labArmor,talisman=labTalisman,dragon=labDragon,curse=labCurse,level=labLevel,target=labTarget,manual=manualAim,weapons=(int[])labWeapons.Clone(),passives=(int[])labPassives.Clone(),evolved=(bool[])labEvolved.Clone()};if(b.name.Length==0)b.name=Catalog.Heroes[heroIndex].Split(',')[0]+" • build "+(slot+1);if(b.name.Length>24)b.name=b.name.Substring(0,24);if(labHits>0&&labMeasurementKey==LabFingerprint()){b.damage=labDamage;b.hits=labHits;b.seconds=Mathf.Max(.25f,time-labFirstHit);b.dps=b.damage/b.seconds;}var list=Favorites;while(list.Count<=slot)list.Add(new FavoriteBuild{name=""});list[slot]=b;if(buildLabActive)save.favorites=list;if(!verifying)FavoritesAccount.Store();return true;}
 bool LoadFavoriteTraining(int slot){if(slot<0||slot>=Favorites.Count||(Favorites[slot]==null||string.IsNullOrEmpty(Favorites[slot].name)))return false;var b=Favorites[slot];if(!buildLabActive)EnterBuildLab();heroIndex=Mathf.Clamp(b.hero,0,5);TryEquipStartingWeapon(b.startingWeapon);labArmor=b.armor;labTalisman=b.talisman;labDragon=Mathf.Clamp(b.dragon,-1,2);labCurse=Mathf.Clamp(b.curse,-1,2);labLevel=Mathf.Clamp(b.level,1,30);labTarget=Mathf.Clamp(b.target,0,2);manualAim=b.manual;for(int i=0;i<6;i++){labWeapons[i]=b.weapons!=null&&b.weapons.Length==6?Mathf.Clamp(b.weapons[i],0,8):0;labPassives[i]=b.passives!=null&&b.passives.Length==6?Mathf.Clamp(b.passives[i],0,5):0;labEvolved[i]=b.evolved!=null&&b.evolved.Length==6&&b.evolved[i]&&labWeapons[i]==8;}ResetLabDps();favoriteName=b.name;favoriteSlot=slot;state=ScreenState.BuildLab;return true;}
 bool FavoriteNormalAllowed(FavoriteBuild b){var a=FavoritesAccount;if(b==null||string.IsNullOrEmpty(b.name)||!HeroUnlockedIn(a,b.hero)||b.startingWeapon< -1||b.startingWeapon>8||!WeaponUnlockedIn(a,b.startingWeapon))return false;foreach(int id in new[]{b.armor,b.talisman})if(id>=0&&(id>=8||(a.relicOwned&(1<<id))==0))return false;if(b.armor>=0&&b.armor%2!=0||b.talisman>=0&&b.talisman%2!=1)return false;if(b.dragon>=0&&(b.dragon>2||(a.dragonUnlocks&(1<<b.dragon))==0))return false;if(b.curse>=0&&(b.curse>2||(a.curseUnlocks&(1<<b.curse))==0))return false;return true;}
 bool EquipFavoriteNormal(int slot){if(slot<0||slot>=Favorites.Count)return false;var b=Favorites[slot];if(!FavoriteNormalAllowed(b)){Toast("Há herói ou itens bloqueados nesta build.");return false;}ExitBuildLab();heroIndex=b.hero;save.NormalizeRelics();save.weaponLoadouts[heroIndex]=b.startingWeapon;save.relicLoadouts[heroIndex*2]=b.armor;save.relicLoadouts[heroIndex*2+1]=b.talisman;selectedDragon=b.dragon;selectedCurse=b.curse;manualAim=b.manual;if(!verifying){save.Store();SaveMenuSettings();}state=ScreenState.Selection;Toast("Build equipada. Armas e níveis evoluem normalmente na partida.");return true;}
 void DrawFavorites(){MainBackdrop();Rect(0,0,1280,720,new Color(.005f,.01f,.02f,.75f));Text("BUILDS FAVORITAS",48,25,1184,55,Style(36,gold,TextAnchor.MiddleLeft,true));Text("DPS do treino: compare com o mesmo nível, alvo e duração. Equipar normal não concede níveis de armas.",50,92,1180,37,Style(14,cyan));for(int i=0;i<5;i++){float y=149+i*84;Frame(12,48,y,1184,78);FavoriteBuild b=i<Favorites.Count?Favorites[i]:null;if(Button((i+1).ToString(),61,y+19,42,39,true,favoriteSlot==i,15))favoriteSlot=i;if(b==null||string.IsNullOrEmpty(b.name)){Text("Slot vazio",120,y+24,700,30,Style(18,Color.white));continue;}Text(b.name+" • "+Catalog.Heroes[Mathf.Clamp(b.hero,0,5)].Split(',')[0],120,y+20,650,24,Style(18,gold,TextAnchor.MiddleLeft,true));Text("DPS "+b.dps.ToString("N1")+" • "+b.seconds.ToString("0.0")+" s • nível "+b.level+" • alvo "+(b.target==0?"comum":b.target==1?"guardião":"glacial")+" • "+(b.startingWeapon>=0&&b.startingWeapon<9?EquipmentWeapons[b.startingWeapon]:"Arma padrão"),120,y+47,650,21,Style(13,cyan));if(Button("TESTAR",821,y+20,143,39,true,false,13))LoadFavoriteTraining(i);if(Button("EQUIPAR NORMAL",982,y+20,228,39,FavoriteNormalAllowed(b),false,12))EquipFavoriteNormal(i);}
  Text("Nome da build do treino",48,589,450,24,Style(15,gold));favoriteName=GUI.TextField(new Rect(48,622,365,37),favoriteName,24);if(Button("SALVAR TREINO NO SLOT "+(favoriteSlot+1),432,620,467,42,buildLabActive,false,14))SaveFavorite(favoriteSlot);if(Button("VOLTAR",927,620,305,42,true,false,16))CloseFavorites();Text("No normal: somente herói, arma, dragão, relíquias e maldição já desbloqueados. Treino é gratuito.",48,676,1184,24,Style(12,Color.white,TextAnchor.MiddleCenter));}
 string VerifyFavorites(){var a=save;bool prior=verifying;int h=heroIndex,pet=selectedDragon,curse=selectedCurse;bool aim=manualAim;verifying=true;save=new SaveData{coins=500};var normal=save;heroIndex=0;selectedDragon=selectedCurse=-1;EnterBuildLab();heroIndex=3;labArmor=4;labTalisman=1;labDragon=0;labCurse=-1;labLevel=15;labTarget=1;labWeapons[1]=8;labPassives[0]=2;labEvolved[1]=true;favoriteName="Ninja distante";ApplyLabBuild();Damage(enemies[0],200);time+=2;if(!SaveFavorite(0)||normal.favorites[0].dps!=100||normal.coins!=500||normal.relicOwned!=0||normal.rescuedHeroes!=1)throw new Exception("Favorite save changes economy or loses DPS");if(EquipFavoriteNormal(0))throw new Exception("Favorite grants locked hero/items");labWeapons[1]=7;SaveFavorite(1);if(normal.favorites[1].dps!=0)throw new Exception("Changed build inherited unrelated DPS");labWeapons[1]=8;ReturnMenu();if(!LoadFavoriteTraining(0)||heroIndex!=3||labWeapons[1]!=8||!labEvolved[1])throw new Exception("Favorite training load failed");ReturnMenu();normal.rescuedHeroes|=1<<3;if(EquipFavoriteNormal(0))throw new Exception("Unlocked hero favorite bypassed relic locks");normal.relicOwned=(1<<4)|(1<<1);if(EquipFavoriteNormal(0))throw new Exception("Favorite bypassed locked dragon");normal.dragonUnlocks=1;if(!EquipFavoriteNormal(0)||heroIndex!=3||EquippedRelic(3,1)!=1)throw new Exception("Unlocked favorite did not equip");StartRun();if(weapons[1]!=1||level!=1||passives[0]!=0)throw new Exception("Favorite grants training weapon ranks in normal play");var roundTrip=JsonUtility.FromJson<SaveData>(JsonUtility.ToJson(normal));if(roundTrip.favorites.Count!=2||roundTrip.favorites[0].name!="Ninja distante"||roundTrip.favorites[0].dps!=100)throw new Exception("Favorite persistence failed");save=a;heroIndex=h;selectedDragon=pet;selectedCurse=curse;manualAim=aim;verifying=prior;ReturnMenu();return "Favorites PASS: named slots, measured DPS/context, persistent JSON, sandbox save economy preserved, training reload, locked normal equip refused and no rank/passive grant in normal run.";}
 IEnumerator CaptureJourney(string folder){verifying=true;Application.runInBackground=true;System.IO.Directory.CreateDirectory(folder);save=new SaveData{coins=250};heroIndex=0;selectedDragon=selectedCurse=-1;StartRun();elementPreviewFrozen=true;SpawnRescue();pos=rescuePosition+Vector2.left;hero.transform.position=pos;cam.transform.position=new Vector3(pos.x,pos.y,-10);yield return Capture(folder,"resgate-heroi-v24");BeginRescue();yield return Capture(folder,"desafio-resgate-v24");ReturnMenu();save=new SaveData{dragonUnlocks=7,curseUnlocks=7};selectedDragon=0;StartRun();elementPreviewFrozen=true;var boss=SpawnEnemy(6,false);boss.p=pos+Vector2.right*3;boss.sprite.transform.position=boss.p;Damage(boss,boss.maxHp*.51f);yield return Capture(folder,"chefe-segunda-fase-v24");OpenBossReward(6,false);yield return Capture(folder,"escolha-bonus-chefe-v24");ReturnMenu();EnterBuildLab();labWeapons[0]=8;favoriteName="Astrônoma de orbes";ApplyLabBuild();manualAim=false;for(int i=0;i<100;i++){time+=.02f;AdvanceWeaponsForCheck(.02f);UpdateShots(.02f);}SaveFavorite(0);OpenFavorites();yield return Capture(folder,"builds-favoritas-v24");ReturnMenu();elementPreviewFrozen=false;Debug.Log("V24 FEATURES CAPTURE PASS");Application.Quit();}
}
